CREATE OR REPLACE FUNCTION public.toggle_message_pin(p_message_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_conv_id uuid;
  v_current_status boolean;
begin
  -- Get conversation_id and check access
  select conversation_id, is_pinned into v_conv_id, v_current_status
  from public.messages
  where id = p_message_id;

  if v_conv_id is null then
    raise exception 'Message not found';
  end if;

  if not public.can_access_conversation(v_conv_id) then
    raise exception 'Access denied to pin this message';
  end if;

  update public.messages
  set is_pinned = not v_current_status
  where id = p_message_id;

  return not v_current_status;
end;
$function$
